SET NAMES utf8mb4;

-- Articolo 1
UPDATE `posts` SET `title_it` = 'Come scegliere la location del matrimonio a Roma',
  `title_en` = 'How to choose your wedding venue in Rome',
  `slug_en` = 'how-to-choose-wedding-venue-rome',
  `excerpt_it` = 'Roma offre centinaia di location per matrimoni, dalle ville storiche ai palazzi nobiliari. Ecco i criteri per scegliere quella giusta per voi, senza sorprese dell''ultimo minuto.',
  `excerpt_en` = 'Rome has hundreds of wedding venues, from historic villas to aristocratic palazzi. Here is how to choose the right one for you, without last-minute surprises.',
  `meta_description_it` = 'Come scegliere la location del matrimonio a Roma: capienza, stile, periodo dell''anno e le zone della città, con i consigli di una wedding planner.',
  `meta_description_en` = 'How to choose a wedding venue in Rome: capacity, style, season and the best areas of the city, with advice from a Rome-based wedding planner.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'Partite dal numero di ospiti: la capienza va verificata per cerimonia, cena e festa.
Lo stile della location dà il tono a tutto il giorno: sceglietela perché vi somiglia.
Per maggio, giugno, settembre e ottobre le location più richieste vanno fermate con largo anticipo.
Appia Antica, Castelli Romani, Aventino: ogni zona di Roma ha un carattere diverso.',
  `sommario_en` = 'Start from your guest count: check capacity for the ceremony, dinner and party.
The venue sets the tone for the whole day: choose one that feels like you.
For May, June, September and October, the most popular venues book up early.
Appia Antica, the Castelli Romani, the Aventine: each part of Rome has its own character.',
  `blocchi` = '[{"tipo": "h2", "it": "Roma, un palcoscenico naturale", "en": "Rome, a natural stage"}, {"tipo": "paragrafo", "it": "Palazzi rinascimentali, ville patrizie immerse nel verde, terrazze che guardano i tetti: a Roma quasi ogni angolo può fare da sfondo al vostro giorno. Proprio per questo orientarsi non è semplice.", "en": "Renaissance palazzi, patrician villas set in green gardens, terraces looking out over the rooftops: in Rome almost any corner can be the backdrop to your day. Which is exactly why choosing is hard."}, {"tipo": "paragrafo", "it": "In questi anni di lavoro come wedding planner a Roma ho imparato che la location è la scelta più importante: è quella che dà il tono a tutto il resto.", "en": "Working as a wedding planner in Rome, I’ve learned that the venue is the most important decision of all: it sets the tone for everything else."}, {"tipo": "h2", "it": "I criteri che contano", "en": "What really matters"}, {"tipo": "h3", "it": "1. Capienza e spazi", "en": "1. Capacity and space"}, {"tipo": "paragrafo", "it": "Partite dal numero di ospiti. Una villa che accoglie 80 persone con eleganza può diventare stretta con 150. Verificate la capienza per la cerimonia, per la cena e per la festa, e chiedete dove si fa l''aperitivo e dove si balla.", "en": "Start with your guest count. A villa that hosts 80 people beautifully can feel cramped with 150. Check the capacity for the ceremony, the dinner and the party, and ask where drinks are served and where people will dance."}, {"tipo": "h3", "it": "2. Stile e atmosfera", "en": "2. Style and atmosphere"}, {"tipo": "paragrafo", "it": "Ogni location ha un carattere. Un palazzo barocco in centro parla di tradizione e grandezza, una villa con il giardino all''italiana di romanticismo, un casale nella campagna romana di semplicità. Sceglietela perché vi somiglia.", "en": "Every venue has a personality. A baroque palazzo in the historic centre speaks of tradition and grandeur, a villa with a formal Italian garden of romance, a farmhouse in the Roman countryside of simplicity. Choose the one that feels like you."}, {"tipo": "h3", "it": "3. Periodo e disponibilità", "en": "3. Season and availability"}, {"tipo": "paragrafo", "it": "Le location più richieste si prenotano con largo anticipo, soprattutto per maggio, giugno, settembre e ottobre. Se la data è flessibile, considerate marzo o novembre: a Roma il clima è spesso ancora mite e la scelta più ampia.", "en": "The most sought-after venues book up well in advance, especially for May, June, September and October. If your date is flexible, consider March or November: the weather in Rome is often still mild, and you’ll have more choice."}, {"tipo": "h2", "it": "Le zone di Roma", "en": "Areas of Rome"}, {"tipo": "paragrafo", "it": "L''Appia Antica ha ville con giardini secolari a pochi minuti dal centro. I Castelli Romani, come Frascati e Castel Gandolfo, aggiungono la vista sul lago e sui vigneti. Tra Trastevere e l''Aventino si nascondono terrazze con il panorama sulla città.", "en": "Along the Appia Antica you’ll find villas with centuries-old gardens just minutes from the centre. The Castelli Romani, such as Frascati and Castel Gandolfo, add views over the lake and the vineyards. Between Trastevere and the Aventine, there are hidden terraces overlooking the city."}, {"tipo": "paragrafo", "it": "Trovare la location giusta richiede tempo e l''occhio di chi conosce la città. È la prima cosa che facciamo insieme, ed è quella che rende tutto il resto più semplice.", "en": "Finding the right venue takes time and the eye of someone who knows the city. It’s the first thing we do together, and it makes everything else easier."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = (SELECT id FROM `media` WHERE path = 'foto/cerimonia-prato-vista-mare.jpg'),
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 1;

-- Articolo 2
UPDATE `posts` SET `title_it` = 'Matrimonio in primavera: i fiori di stagione',
  `title_en` = 'A spring wedding: flowers in season',
  `slug_en` = 'spring-wedding-flowers-in-season',
  `excerpt_it` = 'Peonie, ranuncoli, rose da giardino: quali fiori scegliere per un matrimonio in primavera e come comporli perché incantino i vostri ospiti.',
  `excerpt_en` = 'Peonies, ranunculus, garden roses: which flowers to choose for a spring wedding, and how to arrange them so they delight your guests.',
  `meta_description_it` = 'Quali fiori scegliere per un matrimonio in primavera: peonie, ranuncoli e rose da giardino, quando trovarli e come costruire la palette.',
  `meta_description_en` = 'Which flowers to choose for a spring wedding: peonies, ranunculus and garden roses, when they are in season and how to build your palette.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'Da marzo a giugno la scelta è ampia, ma ogni fiore ha la sua finestra.
Le peonie durano poco: da fine aprile a inizio giugno.
Ranuncoli e rose da giardino danno morbidezza e profumo.
Il segreto è l''equilibrio tra fiori protagonisti, fiori di riempimento e verde.',
  `sommario_en` = 'From March to June the choice is wide, but every flower has its window.
Peonies have a short season: from late April to early June.
Ranunculus and garden roses bring softness and scent.
The secret is balance between statement flowers, fillers and greenery.',
  `blocchi` = '[{"tipo": "h2", "it": "La primavera, un''alleata", "en": "Spring is on your side"}, {"tipo": "paragrafo", "it": "Non c''è stagione più generosa della primavera quando si parla di fiori. Da marzo a giugno la natura offre colori, profumi e consistenze che trasformano qualsiasi spazio in un giardino.", "en": "No season is more generous than spring when it comes to flowers. From March to June, nature offers colours, scents and textures that can turn any space into a garden."}, {"tipo": "paragrafo", "it": "Attenzione però: non tutti i fiori ci sono in tutti i mesi, e la scelta deve tenere conto anche della resistenza al caldo e della durata durante la giornata.", "en": "But be careful: not every flower is available every month, and your choice also needs to account for how well the flowers cope with heat and how long they last through the day."}, {"tipo": "h2", "it": "I fiori protagonisti", "en": "The stars of the season"}, {"tipo": "h3", "it": "Peonie", "en": "Peonies"}, {"tipo": "paragrafo", "it": "Sono il fiore più richiesto per i matrimoni di primavera, e a ragione: petali morbidi e voluminosi, perfetti per bouquet romantici e centrotavola generosi. La loro stagione è breve, da fine aprile a inizio giugno: meglio pianificare per tempo.", "en": "They are the most requested flower for spring weddings, and with good reason: soft, full petals, perfect for romantic bouquets and generous centrepieces. Their season is short, from late April to early June, so plan ahead."}, {"tipo": "h3", "it": "Ranuncoli", "en": "Ranunculus"}, {"tipo": "paragrafo", "it": "Con i loro strati di petali sottilissimi aggiungono raffinatezza a qualsiasi composizione. Esistono in moltissimi colori, dal bianco al rosa cipria, dal pesca al bordeaux, e si adattano a quasi ogni stile.", "en": "With their layers of paper-thin petals, they add refinement to any arrangement. They come in a huge range of colours, from white to powder pink, from peach to burgundy, and suit almost any style."}, {"tipo": "h3", "it": "Rose da giardino", "en": "Garden roses"}, {"tipo": "paragrafo", "it": "Diverse dalle rose classiche, hanno la forma a coppa e un profumo intenso. Varietà come Juliet, Keira e Patience portano nelle composizioni l''atmosfera di un giardino inglese.", "en": "Unlike classic roses, they have a cupped shape and a rich scent. Varieties such as Juliet, Keira and Patience bring the feel of an English garden to any arrangement."}, {"tipo": "h2", "it": "Costruire la palette", "en": "Building your palette"}, {"tipo": "paragrafo", "it": "Il segreto di una composizione riuscita non è usare i fiori più costosi, ma creare armonia tra forme, colori e consistenze. Alternate fiori protagonisti, come peonie e rose da giardino, a fiori di riempimento come lisianthus e astilbe, e a un verde che dia struttura, come eucalipto e ruscus.", "en": "The secret of a beautiful arrangement isn’t using the most expensive flowers, but creating harmony between shapes, colours and textures. Pair statement flowers such as peonies and garden roses with fillers like lisianthus and astilbe, and with greenery that gives structure, like eucalyptus and ruscus."}, {"tipo": "paragrafo", "it": "Il resto lo decide la luce del vostro giorno: è lì che i fiori prendono vita.", "en": "The rest is up to the light on your day: that’s when the flowers come alive."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = NULL,
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 2;

-- Articolo 4
UPDATE `posts` SET `title_it` = 'Budget del matrimonio: come pianificarlo senza sorprese',
  `title_en` = 'Your wedding budget: how to plan it without surprises',
  `slug_en` = 'wedding-budget-plan-without-surprises',
  `excerpt_it` = 'Quali sono le voci di spesa di un matrimonio e quanto pesano sul totale: come distribuire il budget con intelligenza, senza sorprese.',
  `excerpt_en` = 'What goes into a wedding budget and how much each part weighs on the total: how to allocate it wisely, without surprises.',
  `meta_description_it` = 'Come pianificare il budget del matrimonio: le voci di spesa principali, quanto pesano sul totale e come distribuirlo senza sorprese.',
  `meta_description_en` = 'How to plan your wedding budget: the main costs, how much each one weighs on the total and how to allocate it without surprises.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'Location e catering valgono da soli quasi metà del budget.
Foto, video, fiori e allestimenti sono le voci che variano di più.
Conoscere tutte le voci prima di iniziare evita le sorprese.
Investite in ciò che vi emoziona e risparmiate dove non si vede.',
  `sommario_en` = 'Venue and catering alone account for almost half of the budget.
Photography, video, flowers and styling are the costs that vary most.
Knowing every cost before you start avoids surprises.
Invest in what moves you and save where nobody will notice.',
  `blocchi` = '[{"tipo": "h2", "it": "Da dove partire", "en": "Where to start"}, {"tipo": "paragrafo", "it": "Il costo di un matrimonio cambia moltissimo da una coppia all''altra: dipende dalla location, dal numero di ospiti e da quanto volete personalizzare ogni dettaglio. Per questo non ha senso partire da una cifra media.", "en": "The cost of a wedding varies enormously from couple to couple: it depends on the venue, the number of guests and how much you want to personalise every detail. That’s why starting from an average figure makes little sense."}, {"tipo": "paragrafo", "it": "La chiave per evitare sorprese è un''altra: conoscere tutte le voci di spesa *prima* di iniziare.", "en": "The key to avoiding surprises is something else: knowing every cost *before* you start."}, {"tipo": "h2", "it": "Le voci principali", "en": "The main costs"}, {"tipo": "h3", "it": "Location e catering: dal 40 al 50% del budget", "en": "Venue and catering: 40 to 50% of the budget"}, {"tipo": "paragrafo", "it": "Da sole valgono quasi metà della spesa. Il loro peso dipende dalla location e dal tipo di servizio: buffet, servito al tavolo o family style.", "en": "Together they account for almost half of the total. How much they weigh depends on the venue and the type of service: buffet, plated or family style."}, {"tipo": "h3", "it": "Foto e video: dall''8 al 12%", "en": "Photography and video: 8 to 12%"}, {"tipo": "paragrafo", "it": "Insieme ai ricordi, sono ciò che vi resterà del giorno. Il video è una voce a parte, da decidere presto: i professionisti migliori si prenotano in anticipo.", "en": "Along with your memories, they are what you’ll keep from the day. Video is a separate decision, best made early: the best professionals book up well ahead."}, {"tipo": "h3", "it": "Fiori e allestimenti: dall''8 al 15%", "en": "Flowers and styling: 8 to 15%"}, {"tipo": "paragrafo", "it": "Dalla cerimonia ai centrotavola, dal bouquet agli allestimenti: la spesa varia molto con la complessità delle composizioni e con la stagione dei fiori scelti.", "en": "From the ceremony to the centrepieces, from the bouquet to the styling: the cost varies a great deal with how elaborate the arrangements are and with the season of the flowers you choose."}, {"tipo": "h2", "it": "Come usare bene il budget", "en": "Spending it well"}, {"tipo": "paragrafo", "it": "Il segreto non è tagliare, ma scegliere dove investire. Mettete di più in ciò che vi emoziona davvero, la musica, i fiori o la cena, e risparmiate dove non si nota. È esattamente il lavoro che facciamo insieme.", "en": "The secret isn’t cutting back, it’s choosing where to invest. Put more into what truly moves you, whether that’s the music, the flowers or the dinner, and save where nobody will notice. That’s exactly what we work out together."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = (SELECT id FROM `media` WHERE path = 'foto/tavoli-giardino-lampade.jpg'),
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 4;

-- Articolo 5
UPDATE `posts` SET `title_it` = 'Tendenze matrimonio 2026: gli stili dell''anno',
  `title_en` = 'Wedding trends 2026: the styles of the year',
  `slug_en` = 'wedding-trends-2026',
  `excerpt_it` = 'Dal quiet luxury al romanticismo contemporaneo, dalle palette calde alla cena come esperienza: le tendenze che stanno definendo i matrimoni del 2026.',
  `excerpt_en` = 'From quiet luxury to contemporary romance, from warm palettes to dinner as an experience: the trends shaping weddings in 2026.',
  `meta_description_it` = 'Le tendenze matrimonio 2026: quiet luxury, romanticismo contemporaneo, palette calde e la cena come esperienza.',
  `meta_description_en` = 'Wedding trends for 2026: quiet luxury, contemporary romance, warm palettes and dinner as an experience.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'Quiet luxury: materiali belli, niente eccessi.
Romanticismo contemporaneo: tessuti morbidi, toni rosati e ambrati.
Palette calde: borgogna, terracotta, ambra, salvia.
La cena diventa un''esperienza da raccontare.',
  `sommario_en` = 'Quiet luxury: beautiful materials, nothing excessive.
Contemporary romance: soft fabrics, rosy and amber tones.
Warm palettes: burgundy, terracotta, amber, sage.
Dinner becomes an experience worth talking about.',
  `blocchi` = '[{"tipo": "h2", "it": "Un nuovo capitolo", "en": "A new chapter"}, {"tipo": "paragrafo", "it": "Dopo anni di minimalismo e palette neutre, le coppie cercano autenticità, personalizzazione e un''eleganza più calda e avvolgente. Ecco le tendenze che vediamo di più quest''anno.", "en": "After years of minimalism and neutral palettes, couples are looking for authenticity, personal touches and a warmer, more enveloping kind of elegance. These are the trends we’re seeing most this year."}, {"tipo": "h2", "it": "Le tendenze da conoscere", "en": "The trends to know"}, {"tipo": "h3", "it": "1. Quiet luxury", "en": "1. Quiet luxury"}, {"tipo": "paragrafo", "it": "Nato nella moda, nel matrimonio si traduce in materiali pregiati, dettagli curati e un''eleganza che non ha bisogno di farsi notare: tovaglie di lino, candele in cera d''api, ceramiche artigianali. Meno elementi, ma di grande qualità.", "en": "Borrowed from fashion, at a wedding it means fine materials, carefully chosen details and an elegance that doesn’t need to shout: linen tablecloths, beeswax candles, handmade ceramics. Fewer things, but of real quality."}, {"tipo": "h3", "it": "2. Romanticismo contemporaneo", "en": "2. Contemporary romance"}, {"tipo": "paragrafo", "it": "Il romanticismo torna, ma in chiave moderna: via i drappeggi eccessivi, spazio ai fiori a cascata, ai tessuti morbidi, ai toni rosati e ambrati. L''obiettivo è un''atmosfera intima, come un abbraccio.", "en": "Romance is back, with a modern twist: out go the heavy drapes, in come cascading flowers, soft fabrics and rosy, amber tones. The aim is an intimate atmosphere, like an embrace."}, {"tipo": "h3", "it": "3. Palette calde", "en": "3. Warm palettes"}, {"tipo": "paragrafo", "it": "I toni neutri non scompaiono, ma si arricchiscono di accenti caldi: borgogna, terracotta, ambra e verde salvia. Perfetti in autunno, sorprendentemente versatili tutto l''anno.", "en": "Neutral tones aren’t going anywhere, but they’re picking up warm accents: burgundy, terracotta, amber and sage green. Perfect in autumn, and surprisingly versatile all year round."}, {"tipo": "h3", "it": "4. La cena come esperienza", "en": "4. Dinner as an experience"}, {"tipo": "paragrafo", "it": "Il banchetto non è più solo cibo: tavoli imperiali con centrotavola scenografici, menu degustazione con i vini abbinati, show cooking. La cena diventa parte del racconto del matrimonio.", "en": "The wedding dinner is no longer just about food: long imperial tables with striking centrepieces, tasting menus with paired wines, live cooking. Dinner becomes part of the story of the day."}, {"tipo": "paragrafo", "it": "Le tendenze sono un punto di partenza, non una regola: il vostro matrimonio deve somigliare a voi.", "en": "Trends are a starting point, not a rule: your wedding should look like you."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = NULL,
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 5;

-- Articolo 6
UPDATE `posts` SET `title_it` = 'Come scegliere il wedding planner: 10 domande da fare',
  `title_en` = 'How to choose your wedding planner: 10 questions to ask',
  `slug_en` = 'how-to-choose-wedding-planner-10-questions',
  `excerpt_it` = 'Non tutti i wedding planner sono uguali. Ecco le dieci domande da fare al primo incontro per capire se avete trovato la persona giusta.',
  `excerpt_en` = 'Not all wedding planners are the same. Here are the ten questions to ask at your first meeting to know whether you’ve found the right person.',
  `meta_description_it` = 'Come scegliere il wedding planner: le 10 domande da fare al primo incontro, dal metodo di lavoro ai costi, dagli imprevisti ai fornitori.',
  `meta_description_en` = 'How to choose a wedding planner: 10 questions to ask at the first meeting, from working style to fees, contingencies and suppliers.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'Chiedete quanti matrimoni segue nello stesso periodo.
Fatevi raccontare il suo metodo e un imprevisto risolto.
Guardate matrimoni completi, non solo gli scatti migliori.
Pretendete trasparenza su servizio, costi e fornitori consigliati.',
  `sommario_en` = 'Ask how many weddings they handle in the same period.
Ask about their method, and about a problem they solved.
Look at complete weddings, not just the best shots.
Expect transparency on the service, fees and recommended suppliers.',
  `blocchi` = '[{"tipo": "h2", "it": "Perché la scelta conta", "en": "Why the choice matters"}, {"tipo": "paragrafo", "it": "Il wedding planner non è un semplice fornitore: è la persona che vi accompagna per mesi, che gestisce le vostre ansie e che il giorno del matrimonio sarà la vostra ombra silenziosa, perché tutto vada come deve.", "en": "A wedding planner isn’t just another supplier: it’s the person who walks beside you for months, who takes on your worries and who, on the day, will be your quiet shadow, making sure everything goes as it should."}, {"tipo": "paragrafo", "it": "Scegliere quello giusto fa la differenza tra un matrimonio stressante e uno da ricordare. Ecco le domande da fare a ogni primo incontro.", "en": "Choosing the right one makes the difference between a stressful wedding and one to remember. These are the questions to ask at every first meeting."}, {"tipo": "h2", "it": "Le 10 domande", "en": "The 10 questions"}, {"tipo": "domanda", "domanda_it": "1. Quanti matrimoni segui nello stesso periodo?", "domanda_en": "1. How many weddings do you handle at the same time?", "risposta_it": "Chi segue molti matrimoni nello stesso mese non può dedicarvi la stessa attenzione di chi ne segue pochi. Chiedete quanti eventi ha nel vostro stesso periodo.", "risposta_en": "Someone handling many weddings in the same month can’t give you the same attention as someone handling just a few. Ask how many events they have around your date."}, {"tipo": "domanda", "domanda_it": "2. Come imposti il lavoro?", "domanda_en": "2. How do you work?", "risposta_it": "Ogni planner ha il suo metodo: c''è chi lavora con una timeline rigida e chi con un approccio più flessibile. L''importante è che il suo modo di lavorare sia compatibile con il vostro.", "risposta_en": "Every planner has their own method: some work to a strict timeline, others take a more flexible approach. What matters is that their way of working fits yours."}, {"tipo": "domanda", "domanda_it": "3. Posso vedere matrimoni completi che hai organizzato?", "domanda_en": "3. Can I see complete weddings you’ve planned?", "risposta_it": "Le foto migliori del portfolio dicono poco. Chiedete di vedere matrimoni interi: i dettagli, l''atmosfera, la coerenza dello stile dall''inizio alla fine.", "risposta_en": "The best portfolio shots don’t tell you much. Ask to see whole weddings: the details, the atmosphere, how consistent the style is from start to finish."}, {"tipo": "domanda", "domanda_it": "4. Come gestisci gli imprevisti?", "domanda_en": "4. How do you handle the unexpected?", "risposta_it": "Il valore di un planner si vede quando qualcosa va storto. Chiedete esempi concreti di problemi risolti: è il modo migliore per capire esperienza e sangue freddo.", "risposta_en": "A planner shows their worth when something goes wrong. Ask for real examples of problems they’ve solved: it’s the best way to judge experience and composure."}, {"tipo": "domanda", "domanda_it": "5. Quali fornitori consigli, e perché?", "domanda_en": "5. Which suppliers do you recommend, and why?", "risposta_it": "Un buon planner ha una rete di fornitori di fiducia e spiega le sue scelte. Diffidate di chi insiste su un nome senza dire perché, o di chi riceve commissioni non dichiarate.", "risposta_en": "A good planner has a network of trusted suppliers and explains their choices. Be wary of anyone who insists on a name without saying why, or who takes undisclosed commissions."}, {"tipo": "domanda", "domanda_it": "6. Cosa è compreso nel servizio, e cosa no?", "domanda_en": "6. What’s included in your service, and what isn’t?", "risposta_it": "Chiedete un elenco scritto: quanti incontri, quanti sopralluoghi, chi c''è il giorno del matrimonio e fino a che ora. Le sorprese nascono quasi sempre da ciò che non è stato scritto.", "risposta_en": "Ask for it in writing: how many meetings, how many site visits, who is there on the day and until what time. Surprises almost always come from what wasn’t written down."}, {"tipo": "domanda", "domanda_it": "7. Come funzionano costi e pagamenti?", "domanda_en": "7. How do fees and payments work?", "risposta_it": "Fatevi spiegare come è calcolato il compenso, quando si paga e cosa succede se cambiate data. Un preventivo chiaro è il primo segno di un lavoro trasparente.", "risposta_en": "Ask how the fee is calculated, when payments are due and what happens if you change the date. A clear quote is the first sign of transparent work."}, {"tipo": "domanda", "domanda_it": "8. Chi ci sarà il giorno del matrimonio?", "domanda_en": "8. Who will be there on the day?", "risposta_it": "Chiedete se ci sarà la persona con cui avete organizzato tutto, e con quanti assistenti. Il giorno conta avere accanto chi conosce ogni dettaglio.", "risposta_en": "Ask whether the person you planned everything with will be there in person, and with how many assistants. On the day, you want someone beside you who knows every detail."}, {"tipo": "domanda", "domanda_it": "9. Come resteremo in contatto durante la preparazione?", "domanda_en": "9. How will we stay in touch while we plan?", "risposta_it": "Email, telefono, videochiamate, una cartella condivisa: l''importante è sapere come e quando avrete risposte, soprattutto se vivete lontano.", "risposta_en": "Email, phone, video calls, a shared folder: what matters is knowing how and when you’ll get answers, especially if you live far away."}, {"tipo": "domanda", "domanda_it": "10. Qual è il piano B per il meteo?", "domanda_en": "10. What’s the plan B for the weather?", "risposta_it": "Per un matrimonio all''aperto serve sempre un''alternativa pronta, non improvvisata. Chiedete come è stata gestita l''ultima volta che ha piovuto.", "risposta_en": "An outdoor wedding always needs a ready-made alternative, not an improvised one. Ask how they handled the last time it rained."}, {"tipo": "paragrafo", "it": "Se le risposte sono chiare e concrete, siete sulla buona strada.", "en": "If the answers are clear and concrete, you’re on the right track."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = (SELECT id FROM `media` WHERE path = 'foto/navata-chiesa-gipsofila.jpg'),
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 6;

-- Articolo 8
UPDATE `posts` SET `title_it` = 'Tableau de mariage: idee per ogni stile',
  `title_en` = 'Wedding seating chart: ideas for every style',
  `slug_en` = 'wedding-seating-chart-ideas',
  `excerpt_it` = 'Dal classico elegante al creativo: idee per un tableau de mariage che racconti il vostro stile e sorprenda gli ospiti.',
  `excerpt_en` = 'From classic elegance to the creative and unexpected: seating chart ideas that tell your story and surprise your guests.',
  `meta_description_it` = 'Idee per il tableau de mariage, stile per stile: classico, botanico, minimal e creativo.',
  `meta_description_en` = 'Wedding seating chart ideas for every style: classic, botanical, minimal and creative.',
  `meta_title_it` = NULL,
  `meta_title_en` = NULL,
  `sommario_it` = 'È il primo dettaglio che gli ospiti vedono al ricevimento.
Racconta lo stile del matrimonio: classico, botanico, minimal o creativo.
Il supporto conta quanto la grafica: specchi, rami, plexiglass, libri.',
  `sommario_en` = 'It’s the first detail guests see when they arrive at the reception.
It tells the style of your wedding: classic, botanical, minimal or creative.
The material matters as much as the design: mirrors, branches, acrylic, books.',
  `blocchi` = '[{"tipo": "h2", "it": "Molto più di una lista di nomi", "en": "Much more than a list of names"}, {"tipo": "paragrafo", "it": "Il tableau de mariage è il primo elemento che gli ospiti vedono entrando al ricevimento. È l''occasione per dare il tono alla serata e far capire subito lo stile del vostro matrimonio.", "en": "The seating chart is the first thing guests see as they walk into the reception. It’s a chance to set the tone for the evening and show the style of your wedding straight away."}, {"tipo": "paragrafo", "it": "Dimenticate il cartoncino con i nomi stampati: oggi il tableau è un elemento di design a tutti gli effetti.", "en": "Forget the printed card with names on it: today the seating chart is a design piece in its own right."}, {"tipo": "h2", "it": "Idee per ogni stile", "en": "Ideas for every style"}, {"tipo": "h3", "it": "Elegante e classico", "en": "Elegant and classic"}, {"tipo": "paragrafo", "it": "Uno specchio antico con le scritte in calligrafia dorata. Un pannello di velluto con i bigliettini in carta di cotone. Un mobile d''epoca con piccoli vasi e i nomi su etichette floreali.", "en": "An antique mirror with gold calligraphy. A velvet panel with cotton-paper cards. A vintage cabinet with small vases and names written on floral tags."}, {"tipo": "h3", "it": "Botanico e naturale", "en": "Botanical and natural"}, {"tipo": "paragrafo", "it": "Un arco di rami con i bigliettini appesi come foglie. Una parete di muschio con le lettere in legno. Piccole piante grasse come segnaposto, ognuna con il nome di un ospite.", "en": "An arch of branches with cards hanging like leaves. A moss wall with wooden letters. Little succulents as place cards, each with a guest’s name."}, {"tipo": "h3", "it": "Moderno e minimal", "en": "Modern and minimal"}, {"tipo": "paragrafo", "it": "Un pannello di plexiglass trasparente con le scritte in vinile. Una struttura in ferro battuto con cartoncini dalle forme geometriche. Per chi ama le linee pulite e il design contemporaneo.", "en": "A clear acrylic panel with vinyl lettering. A wrought-iron frame with geometric cards. For anyone who loves clean lines and contemporary design."}, {"tipo": "h3", "it": "Creativo e originale", "en": "Creative and unexpected"}, {"tipo": "paragrafo", "it": "Una mappa del mondo per un matrimonio a tema viaggio. Una libreria con i libri che nascondono i nomi dei tavoli. Una composizione di cornici dorate di misure diverse. Un muro di chiavi antiche.", "en": "A world map for a travel-themed wedding. A bookcase where the books hide the table names. A cluster of gold frames in different sizes. A wall of antique keys."}, {"tipo": "paragrafo", "it": "Il tableau più bello è quello che sembra pensato solo per voi.", "en": "The most beautiful seating chart is the one that looks as if it was designed just for you."}]',
  `modified_date` = '2026-10-22',
  `cover_media_id` = NULL,
  `active` = 1,
  `body_it` = NULL,
  `body_en` = NULL
WHERE `id` = 8;

-- Articolo 3: non pubblicato fino alla conferma di Gaia
UPDATE `posts` SET `title_it` = 'Destination wedding in Toscana: tutto quello che dovete sapere', `blocchi` = '[{"tipo": "h2", "it": "Perché la toscana è la meta n.1 per i destination wedding", "en": ""}, {"tipo": "paragrafo", "it": "La Toscana incarna tutto ciò che il mondo ama dell''Italia: paesaggi da cartolina, cucina straordinaria, vini leggendari e un''atmosfera che sembra sospesa nel tempo. Non sorprende che sia la destinazione preferita dalle coppie internazionali per il loro matrimonio.", "en": ""}, {"tipo": "paragrafo", "it": "Ma organizzare un destination wedding in Toscana richiede una pianificazione accurata e una conoscenza profonda del territorio. Ecco tutto quello che dovete sapere.", "en": ""}, {"tipo": "h2", "it": "Le zone più belle per sposarsi in toscana", "en": ""}, {"tipo": "h3", "it": "Val d''orcia: il paesaggio iconico", "en": ""}, {"tipo": "paragrafo", "it": "Patrimonio UNESCO, la Val d''Orcia offre lo sfondo più fotografato della Toscana: colline ondulate, cipressi allineati, borghi medievali. Le ville e gli agriturismi della zona garantiscono privacy assoluta e tramonti indimenticabili.", "en": ""}, {"tipo": "h3", "it": "Chianti: tra vigneti e castelli", "en": ""}, {"tipo": "paragrafo", "it": "Il Chianti è perfetto per chi sogna un matrimonio tra vigneti. Castelli medievali trasformati in resort, cantine storiche, ville rinascimentali: ogni location racconta secoli di storia toscana.", "en": ""}, {"tipo": "h3", "it": "Firenze e dintorni: eleganza rinascimentale", "en": ""}, {"tipo": "paragrafo", "it": "Per chi desidera la vicinanza alla città, le ville medicee intorno a Firenze offrono il perfetto equilibrio tra grandiosità storica e comodità logistica per gli ospiti internazionali.", "en": ""}, {"tipo": "h2", "it": "Logistica e aspetti pratici", "en": ""}, {"tipo": "paragrafo", "it": "Il destination wedding richiede attenzione alla logistica degli ospiti: trasferimenti dall''aeroporto, alloggi, attività nei giorni precedenti e successivi. Un buon wedding planner coordina tutto questo, trasformando il matrimonio in un''esperienza completa di più giorni.", "en": ""}]',
  `cover_media_id` = NULL, `body_it` = NULL, `body_en` = NULL, `active` = 0
WHERE `id` = 3;

-- Articolo 7: non pubblicato fino alla conferma di Gaia
UPDATE `posts` SET `title_it` = 'Matrimonio in Costiera Amalfitana: la guida', `blocchi` = '[{"tipo": "h2", "it": "La costiera amalfitana: un sogno ad occhi aperti", "en": ""}, {"tipo": "paragrafo", "it": "C''è un motivo per cui la Costiera Amalfitana è Patrimonio UNESCO e una delle destinazioni wedding più desiderate al mondo. Il mare cristallino, i borghi arroccati sulle scogliere, i giardini di limoni e le terrazze panoramiche creano uno scenario che nessun allestimento potrà mai superare.", "en": ""}, {"tipo": "paragrafo", "it": "Ma organizzare un matrimonio in Costiera richiede competenza specifica: la logistica è complessa, le location hanno regole precise e la stagionalità gioca un ruolo fondamentale.", "en": ""}, {"tipo": "h2", "it": "Le location iconiche", "en": ""}, {"tipo": "h3", "it": "Ravello: l''eleganza in quota", "en": ""}, {"tipo": "paragrafo", "it": "Arroccata a 350 metri sul mare, Ravello offre panorami che tolgono il fiato. Villa Rufolo e Villa Cimbrone sono le location più celebri, con i loro giardini terrazzati affacciati sull''infinito. Perfetta per matrimoni intimi e raffinati.", "en": ""}, {"tipo": "h3", "it": "Positano: il fascino bohémien", "en": ""}, {"tipo": "paragrafo", "it": "Con le sue case color pastello che scendono verso il mare, Positano è la quintessenza del glamour mediterraneo. Le location qui sono più intime e informali, perfette per chi cerca un''atmosfera rilassata ma sofisticata.", "en": ""}, {"tipo": "h3", "it": "Amalfi: la grandiosità storica", "en": ""}, {"tipo": "paragrafo", "it": "Il Duomo di Amalfi è uno degli sfondi più spettacolari per una cerimonia. La cittadina offre hotel storici con terrazze sul mare e una vivacità che contagia ogni evento.", "en": ""}, {"tipo": "h2", "it": "Aspetti pratici da considerare", "en": ""}, {"tipo": "paragrafo", "it": "Le strade della Costiera sono strette e tortuose: pianificate i trasferimenti con anticipo e considerate barche private per gli spostamenti tra i borghi. Il periodo migliore va da maggio a ottobre, con giugno e settembre come mesi ideali per il clima e la luce.", "en": ""}]',
  `cover_media_id` = NULL, `body_it` = NULL, `body_en` = NULL, `active` = 0
WHERE `id` = 7;
